R=Path(__file__).resolve().parents[1]
OLD=R.parent/'ieantn-ramanujan-source-pv-20261119'
PORTABLE=(R/'MertensPositive/render-support').is_dir()
sys.path.insert(0,str(R/'MertensPositive/render-support' if PORTABLE else OLD/'report-tools/python'))
from latex2mathml.converter import convert
FONT=R/'MertensPositive/render-support/fonts/STIXGeneral.ttf' if PORTABLE else R/'network/Solutions/RamanujanSourcePV.v1/reports/fonts/STIXGeneral.ttf'
